    11	/// Writes the `.fjgraphic` at `path` (created or truncated). `package_json`
    12	/// is `{"module","title","category","description":string|null,
    13	/// "app_version","files":[{"path","size"}…]}`, each path relative to the
    14	/// project's `graphics/` folder, the first exactly `<module>.js` and every
    15	/// other `fonts/<n>` or `assets/<n>`; `data` is the files' bytes
    16	/// concatenated in that order. Answers the `manifest.json` it wrote. NULL
    17	/// with a lowercase sentence naming the value through `err_out` for a NULL
    18	/// argument, a spec that fails its checks, sizes that do not sum to `len`,
    19	/// an archive past a zip without Zip64, or an I/O failure; an input refusal
    20	/// writes nothing.
    21	///
    22	/// # Safety
    23	/// `path` and `package_json` must be NULL or valid NUL-terminated C
    24	/// strings; `data` must be NULL or point to `len` readable bytes; `err_out`
    25	/// must be NULL or a valid pointer to writable `*mut c_char`. Both strings
    26	/// are freed with `rc_string_free`.
    27	#[no_mangle]
    28	pub unsafe extern "C" fn rc_graphic_package_write(
    29	    path: *const c_char,
    30	    package_json: *const c_char,
    31	    data: *const u8,
    32	    len: usize,
    33	    err_out: *mut *mut c_char,
    34	) -> *mut c_char {
    35	    let body = || {
    36	        let path = unsafe { read_cstr(path, "path") }?;
    37	        let package = unsafe { read_cstr(package_json, "package_json") }?;
    38	        if data.is_null() {
    39	            return Err("data is NULL".to_string());
    40	        }
    41	        let data = unsafe { read_bytes(data, len) }?;
    42	        graphic_package::write(&path, &package, &data)
    43	    };
    44	    unsafe {
    45	        fallible_op(
    46	            err_out,
    47	            "writing a graphic package",
    48	            ptr::null_mut(),
    49	            body,
    50	            out_string,
    51	        )
    52	    }
    53	}
