content.content:
  1	//! `rc_graphic_package_write` (spec §11 G-46 (c)), black box through the
  2	//! FFI. The oracles are independent of the implementation: a zip reader
  3	//! written here (end record → central directory → local headers), a bitwise
  4	//! CRC-32 checked against the standard check value, `sha2` for the
  5	//! manifest's checksums, and the manifest's text spelled out in full.
  6	
  7	mod common;
  8	
  9	use std::ffi::c_char;
 10	use std::fs;
 11	use std::path::{Path, PathBuf};
 12	use std::ptr;
 13	
 14	use serde_json::{json, Value};
 15	use sha2::{Digest, Sha256};
 16	
 17	use common::{cstring, take_string};
 18	use framejob_core::ffi_graphic_package::rc_graphic_package_write;
 19	
 20	/// A fresh, empty scratch folder for one test.
 21	fn scratch(tag: &str) -> PathBuf {
 22	    let dir = std::env::temp_dir().join(format!("fjpkg-{}-{tag}", std::process::id()));
 23	    let _ = fs::remove_dir_all(&dir);
 24	    fs::create_dir_all(&dir).expect("a scratch folder");
 25	    dir
 26	}
 27	
 28	/// The manifest the core answers, or its refusal.
 29	fn write(path: &Path, spec: &Value, data: &[u8]) -> Result<String, String> {
 30	    let path = cstring(path.to_str().expect("a UTF-8 path"));
 31	    let spec = cstring(&spec.to_string());
 32	    let mut err: *mut c_char = ptr::null_mut();
 33	    let out = unsafe {
 34	        rc_graphic_package_write(
 35	            path.as_ptr(),
 36	            spec.as_ptr(),
 37	            data.as_ptr(),
 38	            data.len(),
 39	            &mut err,
 40	        )
 41	    };
 42	    match take_string(out) {
 43	        Some(manifest) => {
 44	            assert!(err.is_null(), "a success wrote err_out");
 45	            Ok(manifest)
 46	        }
 47	        None => Err(take_string(err).expect("a refusal writes err_out")),
 48	    }
 49	}
 50	
 51	/// CRC-32 (IEEE) one bit at a time: reflected, init and xorout all ones.
 52	fn crc32(bytes: &[u8]) -> u32 {
 53	    let mut crc = 0xFFFF_FFFFu32;
 54	    for &b in bytes {
 55	        crc ^= u32::from(b);
 56	        for _ in 0..8 {
 57	            crc = if crc & 1 == 1 {
 58	                (crc >> 1) ^ 0xEDB8_8320
 59	            } else {
 60	                crc >> 1
 61	            };
 62	        }
 63	    }
 64	    !crc
 65	}
 66	
 67	fn sha(bytes: &[u8]) -> String {
 68	    Sha256::digest(bytes)
 69	        .iter()
 70	        .map(|b| format!("{b:02x}"))
 71	        .collect()
 72	}
 73	
 74	fn u16_at(b: &[u8], at: usize) -> u16 {
 75	    u16::from_le_bytes([b[at], b[at + 1]])
 76	}
 77	
 78	fn u32_at(b: &[u8], at: usize) -> u32 {
 79	    u32::from_le_bytes([b[at], b[at + 1], b[at + 2], b[at + 3]])
 80	}
 81	
 82	/// One entry as the central directory and its local header both say it.
 83	#[derive(Debug)]
 84	struct Entry {
 85	    name: String,
 86	    data: Vec<u8>,
 87	    crc: u32,
 88	}
 89	
 90	/// Reads the archive the long way, asserting every fixed field G-46 (c)
 91	/// names on both the central and the local record.
 92	fn read_zip(zip: &[u8]) -> Vec<Entry> {
 93	    let end = zip.len() - 22;
 94	    assert_eq!(u32_at(zip, end), 0x0605_4b50, "the end record is last");
 95	    assert_eq!(u16_at(zip, end + 20), 0, "no archive comment");
 96	    let count = usize::from(u16_at(zip, end + 10));
 97	    assert_eq!(u16_at(zip, end + 8), count as u16);
 98	    let central_len = u32_at(zip, end + 12) as usize;
 99	    let mut at = u32_at(zip, end + 16) as usize;
100	    assert_eq!(
101	        at + central_len,
102	        end,
103	        "the central directory ends at the end record"
104	    );
105	    let mut entries = Vec::new();
106	    for _ in 0..count {
107	        assert_eq!(u32_at(zip, at), 0x0201_4b50);
108	        assert_eq!(u16_at(zip, at + 4), 0x031E, "made-by");
109	        assert_eq!(u16_at(zip, at + 6), 10, "version needed");
110	        assert_eq!(u16_at(zip, at + 8), 0x0800, "flag bit 11 alone");
111	        assert_eq!(u16_at(zip, at + 10), 0, "stored");
112	        assert_eq!(u16_at(zip, at + 12), 0, "time 0");
113	        assert_eq!(u16_at(zip, at + 14), 0x0021, "1980-01-01");
114	        let crc = u32_at(zip, at + 16);
115	        let compressed = u32_at(zip, at + 20) as usize;
116	        let size = u32_at(zip, at + 24) as usize;
117	        assert_eq!(compressed, size, "stored: both sizes agree");
118	        let name_len = usize::from(u16_at(zip, at + 28));
119	        assert_eq!(u16_at(zip, at + 30), 0, "no extra field");
120	        assert_eq!(u16_at(zip, at + 32), 0, "no comment");
121	        assert_eq!(u32_at(zip, at + 38), 0o100644 << 16, "external attributes");
122	        let local = u32_at(zip, at + 42) as usize;
123	        let name = String::from_utf8(zip[at + 46..at + 46 + name_len].to_vec()).expect("UTF-8");
124	        assert!(!name.ends_with('/'), "no directory entries");
125	        at += 46 + name_len;
126	
127	        assert_eq!(u32_at(zip, local), 0x0403_4b50);
128	        assert_eq!(u16_at(zip, local + 4), 10);
129	        assert_eq!(u16_at(zip, local + 6), 0x0800);
130	        assert_eq!(u16_at(zip, local + 8), 0);
131	        assert_eq!(u16_at(zip, local + 10), 0);
132	        assert_eq!(u16_at(zip, local + 12), 0x0021);
133	        assert_eq!(u32_at(zip, local + 14), crc, "{name}: local CRC");
134	        assert_eq!(u32_at(zip, local + 18) as usize, size);
135	        assert_eq!(u32_at(zip, local + 22) as usize, size);
136	        assert_eq!(usize::from(u16_at(zip, local + 26)), name_len);
137	        assert_eq!(u16_at(zip, local + 28), 0, "no local extra field");
138	        assert_eq!(&zip[local + 30..local + 30 + name_len], name.as_bytes());
139	        let start = local + 30 + name_len;
140	        entries.push(Entry {
141	            name,
142	            data: zip[start..start + size].to_vec(),
143	            crc,
144	        });
145	    }
146	    entries
147	}
148	
149	const MODULE: &[u8] = b"export function render() { return ''; }\n";
150	const FONT: &[u8] = b"pretend font bytes";
151	const PNG: &[u8] = b"\x89PNG pretend image";
152	
153	/// A module, one font and one asset, and their bytes concatenated.
154	fn package() -> (Value, Vec<u8>) {
155	    let spec = json!({
156	        "module": "lower-third",
157	        "title": "Lower third",
158	        "category": "Titles & Text",
159	        "description": null,
160	        "app_version": "0.3.19",
161	        "files": [
162	            {"path": "lower-third.js", "size": MODULE.len()},
163	            {"path": "fonts/Anton.ttf", "size": FONT.len()},
164	            {"path": "assets/red.png", "size": PNG.len()},
165	        ],
166	    });
167	    (spec, [MODULE, FONT, PNG].concat())
168	}
169	
170	#[test]
171	fn the_bitwise_oracle_has_the_standard_check_value() {
172	    assert_eq!(crc32(b"123456789"), 0xCBF4_3926);
173	}
174	
175	#[test]
176	fn each_entry_carries_the_ieee_crc_of_its_bytes() {
177	    let dir = scratch("crc");
178	    let path = dir.join("a.fjgraphic");
179	    let (spec, data) = package();
180	    write(&path, &spec, &data).expect("written");
181	    let entries = read_zip(&fs::read(&path).expect("the package"));
182	    assert_eq!(entries.len(), 4);
183	    for entry in &entries {
184	        assert_eq!(entry.crc, crc32(&entry.data), "{}", entry.name);
185	    }
186	}
187	
188	#[test]
