 28	/// The manifest the core answers, or its refusal.
 29	fn write(path: &Path, spec: &Value, data: &[u8]) -> Result<String, String> {
 30	    let path = cstring(path.to_str().expect("a UTF-8 path"));
 31	    let spec = cstring(&spec.to_string());
 32	    let mut err: *mut c_char = ptr::null_mut();
 33	    let out = unsafe {
 34	        rc_graphic_package_write(
 35	            path.as_ptr(),
 36	            spec.as_ptr(),
 37	            data.as_ptr(),
 38	            data.len(),
 39	            &mut err,
 40	        )
 41	    };
 42	    match take_string(out) {
 43	        Some(manifest) => {
 44	            assert!(err.is_null(), "a success wrote err_out");
 45	            Ok(manifest)
 46	        }
 47	        None => Err(take_string(err).expect("a refusal writes err_out")),
 48	    }
 49	}
