 82	/// One entry as the central directory and its local header both say it.
 83	#[derive(Debug)]
 84	struct Entry {
 85	    name: String,
 86	    data: Vec<u8>,
 87	    crc: u32,
 88	}
 89	
 90	/// Reads the archive the long way, asserting every fixed field G-46 (c)
 91	/// names on both the central and the local record.
 92	fn read_zip(zip: &[u8]) -> Vec<Entry> {
 93	    let end = zip.len() - 22;
 94	    assert_eq!(u32_at(zip, end), 0x0605_4b50, "the end record is last");
 95	    assert_eq!(u16_at(zip, end + 20), 0, "no archive comment");
 96	    let count = usize::from(u16_at(zip, end + 10));
 97	    assert_eq!(u16_at(zip, end + 8), count as u16);
 98	    let central_len = u32_at(zip, end + 12) as usize;
 99	    let mut at = u32_at(zip, end + 16) as usize;
100	    assert_eq!(
101	        at + central_len,
102	        end,
103	        "the central directory ends at the end record"
104	    );
105	    let mut entries = Vec::new();
106	    for _ in 0..count {
107	        assert_eq!(u32_at(zip, at), 0x0201_4b50);
108	        assert_eq!(u16_at(zip, at + 4), 0x031E, "made-by");
109	        assert_eq!(u16_at(zip, at + 6), 10, "version needed");
110	        assert_eq!(u16_at(zip, at + 8), 0x0800, "flag bit 11 alone");
111	        assert_eq!(u16_at(zip, at + 10), 0, "stored");
112	        assert_eq!(u16_at(zip, at + 12), 0, "time 0");
113	        assert_eq!(u16_at(zip, at + 14), 0x0021, "1980-01-01");
114	        let crc = u32_at(zip, at + 16);
115	        let compressed = u32_at(zip, at + 20) as usize;
116	        let size = u32_at(zip, at + 24) as usize;
117	        assert_eq!(compressed, size, "stored: both sizes agree");
118	        let name_len = usize::from(u16_at(zip, at + 28));
119	        assert_eq!(u16_at(zip, at + 30), 0, "no extra field");
120	        assert_eq!(u16_at(zip, at + 32), 0, "no comment");
121	        assert_eq!(u32_at(zip, at + 38), 0o100644 << 16, "external attributes");
122	        let local = u32_at(zip, at + 42) as usize;
123	        let name = String::from_utf8(zip[at + 46..at + 46 + name_len].to_vec()).expect("UTF-8");
124	        assert!(!name.ends_with('/'), "no directory entries");
125	        at += 46 + name_len;
126	
127	        assert_eq!(u32_at(zip, local), 0x0403_4b50);
128	        assert_eq!(u16_at(zip, local + 4), 10);
129	        assert_eq!(u16_at(zip, local + 6), 0x0800);
130	        assert_eq!(u16_at(zip, local + 8), 0);
131	        assert_eq!(u16_at(zip, local + 10), 0);
132	        assert_eq!(u16_at(zip, local + 12), 0x0021);
133	        assert_eq!(u32_at(zip, local + 14), crc, "{name}: local CRC");
134	        assert_eq!(u32_at(zip, local + 18) as usize, size);
135	        assert_eq!(u32_at(zip, local + 22) as usize, size);
136	        assert_eq!(usize::from(u16_at(zip, local + 26)), name_len);
137	        assert_eq!(u16_at(zip, local + 28), 0, "no local extra field");
138	        assert_eq!(&zip[local + 30..local + 30 + name_len], name.as_bytes());
139	        let start = local + 30 + name_len;
140	        entries.push(Entry {
141	            name,
142	            data: zip[start..start + size].to_vec(),
143	            crc,
144	        });
145	    }
146	    entries
147	}
