332	        (
333	            base.clone(),
334	            data[..data.len() - 1].to_vec(),
335	            &format!(
336	                "the files' sizes sum to {} bytes, but data holds {}",
337	                data.len(),
338	                data.len() - 1
339	            )
340	            .leak()[..],
341	        ),
342	    ];
343	    for (n, (spec, bytes, sentence)) in cases.iter().enumerate() {
344	        let path = dir.join(format!("{n}.fjgraphic"));
345	        let refusal = write(&path, spec, bytes).expect_err("refused");
346	        assert!(
347	            refusal.contains(sentence),
348	            "case {n}: {refusal:?} does not hold {sentence:?}"
349	        );
