375	/// The in-package paths and manifest names a package of `given` (each a
376	/// project-relative path, holding its own path's bytes) gets.
377	fn names_of(dir: &Path, given: &[&str]) -> (Vec<String>, Vec<String>) {
378	    let path = dir.join("names.fjgraphic");
379	    let mut files = vec![json!({"path": "lower-third.js", "size": MODULE.len()})];
380	    let mut data = MODULE.to_vec();
381	    for name in given {
382	        files.push(json!({"path": name, "size": name.len()}));
383	        data.extend_from_slice(name.as_bytes());
384	    }
385	    let (mut spec, _) = package();
386	    spec["files"] = Value::Array(files);
387	    let manifest = write(&path, &spec, &data).expect("written");
388	    let entries = read_zip(&fs::read(&path).unwrap());
389	    let parsed: Value = serde_json::from_str(&manifest).unwrap();
390	    let listed = parsed["files"].as_array().unwrap();
391	    for (i, entry) in entries.iter().skip(1).enumerate() {
392	        assert_eq!(listed[i]["path"], entry.name.as_str());
393	        assert_eq!(listed[i]["sha256"], sha(&entry.data).as_str());
394	    }
395	    for (i, name) in given.iter().enumerate() {
396	        assert_eq!(entries[i + 2].data, name.as_bytes(), "{name}'s bytes");
397	    }
398	    (
399	        entries.iter().skip(2).map(|e| e.name.clone()).collect(),
400	        listed

