  1	//! `Library::usage()` (spec §11 G-46 (b)): the font blobs a parse or a
  2	//! measure selected, directly or as a fallback, and the image assets it
  3	//! resolved — cumulative per library, by the blob's index in `new()`.
  4	
  5	mod common;
  6	
  7	use std::collections::BTreeMap;
  8	use std::fs;
  9	
 10	use common::{assets, fonts, render, svg, FONTS};
 11	use graphic::{measure_text, FontStyle, Library, TextFont, Usage};
 12	
 13	/// The index of the bundled font `file` in `common::fonts()`'s order.
 14	fn index_of(file: &str) -> usize {
 15	    let mut names: Vec<String> = fs::read_dir(FONTS)
 16	        .expect("the bundled fonts directory")
 17	        .map(|entry| entry.expect("an entry").file_name().into_string().unwrap())
 18	        .filter(|name| name.ends_with(".ttf"))
 19	        .collect();
 20	    names.sort();
 21	    names
 22	        .iter()
 23	        .position(|name| name == file)
 24	        .unwrap_or_else(|| panic!("{file} is not a bundled font"))
 25	}
 26	
 27	fn font_bytes(file: &str) -> Vec<u8> {
 28	    fs::read(format!("{FONTS}/{file}")).expect("a bundled font")
 29	}
 30	
 31	fn text(family: &str, body: &str) -> String {
 32	    svg(
 33	        200,
 34	        60,
 35	        &format!("<text x=\"4\" y=\"44\" font-family=\"{family}\" font-size=\"40\">{body}</text>"),
 36	    )
 37	}
 38	
 39	fn image(href: &str) -> String {
 40	    svg(
 41	        12,
 42	        12,
 43	        &format!("<image x=\"2\" y=\"2\" width=\"8\" height=\"8\" href=\"{href}\"/>"),
 44	    )
 45	}
 46	
 47	fn inked(buf: &[u8]) -> bool {
 48	    buf.chunks(4).any(|px| px[3] != 0)
 49	}
 50	
 51	fn usage(fonts: Vec<usize>, assets: &[&str]) -> Usage {
 52	    Usage {
 53	        fonts,
 54	        assets: assets.iter().map(|name| name.to_string()).collect(),
 55	    }
 56	}
 57	
 58	#[test]
 59	fn a_drawn_family_records_its_blob() {
 60	    let lib = Library::new(fonts(), BTreeMap::new());
 61	    render(&lib, &text("Anton", "Hello"), 200, 60);
 62	    assert_eq!(lib.usage(), usage(vec![index_of("Anton-Regular.ttf")], &[]));
 63	
 64	    let lib = Library::new(fonts(), BTreeMap::new());
 65	    render(&lib, &text("serif", "Hello"), 200, 60);
 66	    assert_eq!(lib.usage(), usage(vec![index_of("SourceSerif4.ttf")], &[]));
 67	
 68	    let lib = Library::new(fonts(), BTreeMap::new());
 69	    let (_, warnings) = render(&lib, &text("No Such Family", "Hello"), 200, 60);
 70	    assert!(!warnings.is_empty(), "a missing family is warned");
 71	    assert_eq!(lib.usage(), Usage::default());
 72	}
 73	
 74	#[test]
 75	fn a_fallback_records_both_faces() {
 76	    // Greek alpha: Source Sans 3 has it, Anton does not. Anton alone draws
 77	    // only its missing-glyph box, the same box it draws for Cyrillic Zhe.
 78	    let alpha = text("Anton", "\u{3b1}");
 79	    let alone = Library::new(vec![font_bytes("Anton-Regular.ttf")], BTreeMap::new());
 80	    let (boxed, _) = render(&alone, &alpha, 200, 60);
 81	    let (zhe, _) = render(&alone, &text("Anton", "\u{416}"), 200, 60);
 82	    assert!(
 83	        inked(&boxed) && boxed == zhe,
 84	        "Anton alone draws the missing-glyph box"
 85	    );
 86	    assert_eq!(alone.usage(), usage(vec![0], &[]));
 87	
 88	    let pair = Library::new(
 89	        vec![
 90	            font_bytes("Anton-Regular.ttf"),
 91	            font_bytes("SourceSans3.ttf"),
 92	        ],
 93	        BTreeMap::new(),
 94	    );
 95	    let (out, _) = render(&pair, &alpha, 200, 60);
 96	    assert!(
 97	        inked(&out) && out != boxed,
 98	        "Source Sans 3 draws the alpha as a fallback"
 99	    );
100	    assert_eq!(pair.usage(), usage(vec![0, 1], &[]));
101	}
102	
103	#[test]
104	fn measure_alone_records_its_face() {
105	    let lib = Library::new(fonts(), BTreeMap::new());
106	    let font = TextFont {
107	        family: "Anton".to_string(),
108	        size: 40.0,
109	        weight: 400,
110	        style: FontStyle::Normal,
111	        letter_spacing: 0.0,
112	        preserve_space: false,
113	    };
114	    measure_text(&lib, "Hello", &font).expect("a measure");
115	    assert_eq!(lib.usage(), usage(vec![index_of("Anton-Regular.ttf")], &[]));
116	}
117	
118	#[test]
119	fn only_a_drawn_image_asset_is_recorded() {
120	    let mut all = assets();
121	    all.insert("notes.txt".to_string(), b"not an image".to_vec());
122	    let lib = Library::new(fonts(), all);
123	    render(&lib, &image("red.png"), 12, 12);
124	    let (_, warnings) = render(&lib, &image("notes.txt"), 12, 12);
125	    assert!(!warnings.is_empty(), "a non-image asset is warned");
126	    let (_, warnings) = render(&lib, &image("missing.png"), 12, 12);
127	    assert!(!warnings.is_empty(), "a missing href is warned");
128	    assert_eq!(lib.usage(), usage(vec![], &["red.png"]));
129	}
130	
131	#[test]
132	fn a_nested_svg_assets_text_records_its_face() {
133	    let label = svg(
134	        8,
135	        8,
136	        "<text x=\"0\" y=\"7\" font-family=\"Anton\" font-size=\"8\">A</text>",
137	    );
138	    let mut all = BTreeMap::new();
139	    all.insert("label.svg".to_string(), label.into_bytes());
140	    let lib = Library::new(fonts(), all);
141	    render(&lib, &image("label.svg"), 12, 12);
142	    assert_eq!(
143	        lib.usage(),
144	        usage(vec![index_of("Anton-Regular.ttf")], &["label.svg"])
145	    );
146	}
147	
148	#[test]
149	fn a_faceless_blob_counts_in_the_indexes() {
150	    let lib = Library::new(
151	        vec![b"not a font".to_vec(), font_bytes("Anton-Regular.ttf")],
152	        BTreeMap::new(),
153	    );
154	    assert_eq!(lib.warnings().len(), 1);
155	    render(&lib, &text("Anton", "Hello"), 200, 60);
156	    assert_eq!(lib.usage(), usage(vec![1], &[]));
157	}
158	
159	#[test]
160	fn usage_accumulates_and_is_per_library() {
161	    let lib = Library::new(fonts(), assets());
162	    let other = Library::new(fonts(), assets());
163	    render(&lib, &text("Anton", "Hello"), 200, 60);
164	    render(&lib, &image("steel.jpg"), 12, 12);
165	    render(&lib, &text("serif", "Hello"), 200, 60);
166	    render(&lib, &image("red.png"), 12, 12);
167	    let mut want = vec![index_of("Anton-Regular.ttf"), index_of("SourceSerif4.ttf")];
168	    want.sort();
169	    assert_eq!(lib.usage(), usage(want, &["red.png", "steel.jpg"]));
170	    assert_eq!(other.usage(), Usage::default());
171	}
